def strategy(history, rng):
    n = len(history)
    if n >= 99:
        return 'D'
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    last_my = my[-1]
    last_opp = op[-1]
    prev_my = my[-2] if n >= 2 else 'C'

    total_op_D = 0
    r5 = 0
    r10 = 0
    r20 = 0
    unprovoked = 0

    for i, o in enumerate(op):
        if o == 'D':
            total_op_D += 1
            age = n - i
            if age <= 5:
                r5 += 1
            if age <= 10:
                r10 += 1
            if age <= 20:
                r20 += 1
            if i == 0 or my[i - 1] == 'C':
                unprovoked += 1

    punish = 0
    no_punish = 0
    for i in range(n - 1):
        if my[i] == 'D' and op[i] == 'C':
            if op[i + 1] == 'D':
                punish += 1
            else:
                no_punish += 1

    if n < 8:
        if last_opp == 'D':
            return 'D' if total_op_D > 1 else 'C'
        return 'C'

    if (
        last_opp == 'C'
        and no_punish > 0
        and no_punish > punish
        and (total_op_D <= 2 or (n >= 30 and total_op_D * 5 <= n))
        and r10 <= 1
    ):
        return 'D'

    if total_op_D == 0:
        if n == 80:
            return 'D'
        if n == 81:
            return 'C'
        if n >= 82:
            return 'D'
        return 'C'

    if (
        punish == 0
        and no_punish == 0
        and total_op_D <= 1
        and r20 <= 1
        and last_opp == 'C'
        and last_my == 'C'
        and n == 80
    ):
        return 'D'

    if total_op_D * 3 > n or r20 >= 8 or (r10 >= 5 and last_opp == 'D'):
        if last_opp == 'C' and r10 <= 1 and r5 == 0:
            return 'C'
        return 'D'

    if last_opp == 'C':
        return 'C'

    if r5 >= 4:
        return 'D'

    if last_my == 'C' and prev_my == 'D':
        if r5 >= 3:
            return 'D'
        return 'C'

    if last_my == 'D':
        if total_op_D <= max(2, n // 10) and r5 <= 2 and rng.random() < 0.3:
            return 'C'
        if r5 <= 1 and total_op_D <= max(3, n // 6):
            return 'C'
        return 'D'

    if total_op_D <= 1 and unprovoked <= 1 and rng.random() < 0.35:
        return 'C'

    if total_op_D <= 3 and r5 == 1 and rng.random() < 0.2:
        return 'C'

    return 'D'
